    public int orangesRotting(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int fresh = 0;
        int minutes = 0;
        PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(cell -> cell[2]));

        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] == 2) {
                    heap.offer(new int[]{row, col, 0});
                } else if (grid[row][col] == 1) {
                    fresh++;
                }
            }
        }

        while (!heap.isEmpty()) {
            int[] cell = heap.poll();
            int row = cell[0];
            int col = cell[1];
            int time = cell[2];
            minutes = Math.max(minutes, time);
            for (int[] direction : DIRECTIONS) {
                int nextRow = row + direction[0];
                int nextCol = col + direction[1];
                if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                    continue;
                }
                if (grid[nextRow][nextCol] != 1) {
                    continue;
                }
                int nextTime = time + 1;
                grid[nextRow][nextCol] = 2;
                fresh--;
                heap.offer(new int[]{nextRow, nextCol, nextTime});
            }
        }

        return fresh == 0 ? minutes : -1;
    }
}

class Solution {
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public int orangesRotting(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int fresh = 0;
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == 1) {
                    fresh++;
                }
            }
        }

        int minutes = 0;
        while (fresh > 0) {
            boolean changed = false;
            for (int row = 0; row < rows; row++) {
                for (int col = 0; col < cols; col++) {
                    if (grid[row][col] != 2) {
                        continue;
                    }
                    for (int[] direction : DIRECTIONS) {
                        int nextRow = row + direction[0];
                        int nextCol = col + direction[1];
                        if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                            continue;
                        }
                        if (grid[nextRow][nextCol] != 1) {
                            continue;
                        }
                        grid[nextRow][nextCol] = 3;
                        fresh--;
                        changed = true;
                    }
                }
            }
            if (!changed) {
                return -1;
            }
            for (int row = 0; row < rows; row++) {
                for (int col = 0; col < cols; col++) {
                    if (grid[row][col] == 3) {
                        grid[row][col] = 2;
                    }
                }
            }
            minutes++;
        }

        return minutes;
    }
}
